<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/app/admin_ui.php';
require_once dirname(__DIR__) . '/app/event_proposals.php';

$admin=coveted_require_system_admin();
$pdo=coveted_db();
$error='';
$notice='';
$playbookRef=trim((string)($_GET['playbook'] ?? $_POST['playbook_ref'] ?? ''));

if ($_SERVER['REQUEST_METHOD']==='POST') {
    coveted_require_csrf();
    try {
        $playbookRef=coveted_event_playbook_save($admin,$_POST,$pdo);
        $notice='Event Playbook saved.';
    } catch (InvalidArgumentException $e) { $error=$e->getMessage(); }
      catch (Throwable $e) { error_log('Event Playbook workspace failed: '.$e->getMessage()); $error='Unable to save that Event Playbook right now.'; }
}

$ready=coveted_event_proposal_schema_available($pdo);
$playbooks=$ready?coveted_event_playbooks($admin,true,$pdo):[];
$selected=$playbookRef!==''?coveted_event_playbook_by_ref($admin,$playbookRef,$pdo):null;
$joinLines=static fn(array $items):string=>implode("\n",array_map(static fn($v):string=>(string)$v,$items));

coveted_page_start('Event Playbooks','',true);
coveted_admin_ui_start($admin,'event-playbooks','Event Playbooks');
?>
<div class="cv-admin-page-head"><div><span class="cv-eyebrow">EVENT PLAYBOOKS</span><h1>Reusable operating patterns.</h1><p>Define the event shape once so the Opportunity Engine, Admin Agent, Proposal workflow and Production Workspace all speak the same language.</p></div><div class="cv-admin-event-top-actions"><a class="cv-button cv-button-soft" href="/admin/event-opportunities.php">Opportunities</a><a class="cv-button cv-button-soft" href="/admin/event-proposals.php">Proposals</a><a class="cv-button cv-button-soft" href="/admin/event-playbooks.php">New Playbook</a></div></div>
<?php if($error!==''):?><div class="cv-alert cv-alert-error"><?=coveted_e($error)?></div><?php endif;?><?php if($notice!==''):?><div class="cv-alert"><?=coveted_e($notice)?></div><?php endif;?><?php if(!$ready):?><div class="cv-alert cv-alert-error"><strong>Migration required.</strong> Import the Event Proposals + Playbooks migration first.</div><?php endif;?>
<?php if($ready):?><div class="cv-admin-dashboard-grid cv-admin-section-gap"><section class="cv-admin-panel"><div class="cv-admin-panel-head"><div><span class="cv-eyebrow">LIBRARY</span><h2><?=count($playbooks)?> Playbooks</h2></div></div><div class="cv-admin-list"><?php foreach($playbooks as $pb):?><a class="cv-admin-list-row" href="/admin/event-playbooks.php?playbook=<?=coveted_e(rawurlencode((string)$pb['public_id']))?>"><span class="cv-admin-list-copy"><strong><?=coveted_e((string)$pb['name'])?></strong><small><?=coveted_e(ucwords(str_replace('_',' ',(string)$pb['event_type'])))?> · <?=(int)$pb['default_capacity']?> guests · <?=(int)$pb['default_duration_minutes']?> min</small></span><span class="cv-status"><?=coveted_e(ucfirst((string)$pb['status']))?></span></a><?php endforeach;?></div></section>
<section class="cv-admin-panel"><div class="cv-admin-panel-head"><div><span class="cv-eyebrow"><?=$selected?'EDIT PLAYBOOK':'NEW PLAYBOOK'?></span><h2><?=$selected?coveted_e((string)$selected['name']):'Build a custom Playbook'?></h2></div></div><form method="post" class="cv-admin-form-grid"><input type="hidden" name="csrf_token" value="<?=coveted_e(coveted_csrf_token())?>"><input type="hidden" name="playbook_ref" value="<?=coveted_e((string)($selected['public_id']??''))?>"><label>Name<input name="name" value="<?=coveted_e((string)($selected['name']??''))?>" required></label><label>Key<input name="playbook_key" value="<?=coveted_e((string)($selected['playbook_key']??''))?>" placeholder="custom_event"></label><label>Event type<select name="event_type"><?php foreach(['regular','mystery','private_table','member_plus_one','session'] as $v):?><option value="<?=$v?>" <?=(string)($selected['event_type']??'regular')===$v?'selected':''?>><?=coveted_e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></label><label>Audience<select name="audience"><option value="group" <?=(string)($selected['audience']??'group')==='group'?'selected':''?>>Group</option><option value="invitation_only" <?=(string)($selected['audience']??'group')==='invitation_only'?'selected':''?>>Invitation only</option></select></label><label>Duration minutes<input type="number" min="30" max="720" name="default_duration_minutes" value="<?=(int)($selected['default_duration_minutes']??150)?>"></label><label>Capacity<input type="number" min="1" max="1000" name="default_capacity" value="<?=(int)($selected['default_capacity']??20)?>"></label><label>Location visibility<select name="location_visibility"><option value="immediate" <?=(string)($selected['location_visibility']??'immediate')==='immediate'?'selected':''?>>Immediate</option><option value="scheduled_reveal" <?=(string)($selected['location_visibility']??'')==='scheduled_reveal'?'selected':''?>>Scheduled reveal</option><option value="host_only" <?=(string)($selected['location_visibility']??'')==='host_only'?'selected':''?>>Host only</option></select></label><label>Status<select name="status"><option value="active" <?=(string)($selected['status']??'active')==='active'?'selected':''?>>Active</option><option value="archived" <?=(string)($selected['status']??'')==='archived'?'selected':''?>>Archived</option></select></label><label><input type="checkbox" name="plus_one_allowed" value="1" <?=!empty($selected['plus_one_allowed'])?'checked':''?>> +1 allowed</label><label class="cv-admin-form-span">Description<textarea name="description" rows="3"><?=coveted_e((string)($selected['description']??''))?></textarea></label><label class="cv-admin-form-span">Required host roles · one per line<textarea name="required_host_roles" rows="3"><?=coveted_e($joinLines((array)($selected['required_host_roles_json']??[])))?></textarea></label><label class="cv-admin-form-span">Recommended benefits · one per line<textarea name="recommended_benefits" rows="3"><?=coveted_e($joinLines((array)($selected['recommended_benefits_json']??[])))?></textarea></label><label class="cv-admin-form-span">Guest cadence · one per line<textarea name="guest_cadence" rows="3"><?=coveted_e($joinLines((array)($selected['guest_cadence_json']??[])))?></textarea></label><label class="cv-admin-form-span">Run of show · one step per line<textarea name="run_of_show" rows="5"><?=coveted_e($joinLines((array)($selected['run_of_show_json']??[])))?></textarea></label><label class="cv-admin-form-span">Production items · one per line<textarea name="production_items" rows="5"><?=coveted_e($joinLines((array)($selected['production_items_json']??[])))?></textarea></label><label class="cv-admin-form-span">Closeout · one per line<textarea name="closeout" rows="4"><?=coveted_e($joinLines((array)($selected['closeout_json']??[])))?></textarea></label><button class="cv-button cv-button-primary" type="submit">Save Playbook</button></form></section></div><?php endif;?>
<section class="cv-admin-panel cv-admin-section-gap"><div class="cv-admin-panel-head"><div><span class="cv-eyebrow">AGENT SYSTEM</span><h2>Playbooks are operational knowledge.</h2></div><span class="cv-pill">Agent brain</span></div><p>The Admin Agent receives active Playbook names, event types, capacity, duration, required host roles, recommended benefits and run-of-show structure. It can recommend a Playbook and explain the fit, but approval and event conversion remain System Admin actions.</p></section>
